macro_rules! deps {
    () => {
        Section!();
        SectionId!();
        Metadata!();
        SectionBodyIdsLut!();
    };
}

macro_rules! File {
    () => {
        deps!();
        # [doc = " High level `git-config` reader and writer."] # [doc = ""] # [doc = " This is the full-featured implementation that can deserialize, serialize,"] # [doc = " and edit `git-config` files without loss of whitespace or comments."] # [doc = ""] # [doc = " # 'multivar' behavior"] # [doc = ""] # [doc = " `git` is flexible enough to allow users to set a key multiple times in"] # [doc = " any number of identically named sections. When this is the case, the key"] # [doc = " is known as a _\"multivar\"_. In this case, [`raw_value()`] follows the"] # [doc = " \"last one wins\"."] # [doc = ""] # [doc = " Concretely, the following config has a multivar, `a`, with the values"] # [doc = " of `b`, `c`, and `d`, while `e` is a single variable with the value"] # [doc = " `f g h`."] # [doc = ""] # [doc = " ```text"] # [doc = " [core]"] # [doc = "     a = b"] # [doc = "     a = c"] # [doc = " [core]"] # [doc = "     a = d"] # [doc = "     e = f g h"] # [doc = " ```"] # [doc = ""] # [doc = " Calling methods that fetch or set only one value (such as [`raw_value()`])"] # [doc = " key `a` with the above config will fetch `d` or replace `d`, since the last"] # [doc = " valid config key/value pair is `a = d`:"] # [doc = ""] # [doc = " # Filtering"] # [doc = ""] # [doc = " All methods exist in a `*_filter(…, filter)` version to allow skipping sections by"] # [doc = " their metadata. That way it's possible to select values based on their `gix_sec::Trust`"] # [doc = " for example, or by their location."] # [doc = ""] # [doc = " Note that the filter may be executed even on sections that don't contain the key in question,"] # [doc = " even though the section will have matched the `name` and `subsection_name` respectively."] # [doc = ""] # [doc = " ```"] # [doc = " # use std::borrow::Cow;"] # [doc = " # use std::convert::TryFrom;"] # [doc = " # let git_config = gix_config::File::try_from(\"[core]a=b\\n[core]\\na=c\\na=d\").unwrap();"] # [doc = " assert_eq!(git_config.raw_value(\"core.a\").unwrap().as_ref(), \"d\");"] # [doc = " ```"] # [doc = ""] # [doc = " Consider the `multi` variants of the methods instead, if you want to work"] # [doc = " with all values."] # [doc = ""] # [doc = " # Equality"] # [doc = ""] # [doc = " In order to make it useful, equality will ignore all non-value bearing information, hence compare"] # [doc = " only sections and their names, as well as all of their values. The ordering matters, of course."] # [doc = ""] # [doc = " [`raw_value()`]: Self::raw_value"] # [derive (Eq , Clone , Debug , Default)] pub struct File < 'event > { # [doc = " The list of events that occur before any section. Since a"] # [doc = " `git-config` file prohibits global values, this vec is limited to only"] # [doc = " comment, newline, and whitespace events."] pub (crate) frontmatter_events : crate :: parse :: FrontMatterEvents < 'event > , # [doc = " Frontmatter events to be placed after the given section."] pub (crate) frontmatter_post_section : HashMap < SectionId , crate :: parse :: FrontMatterEvents < 'event > > , # [doc = " Section name to section id lookup tree, with section bodies for subsections being in a non-terminal"] # [doc = " variant of `SectionBodyIds`."] pub (crate) section_lookup_tree : HashMap < section :: Name < 'event > , Vec < SectionBodyIdsLut < 'event > > > , # [doc = " This indirection with the SectionId as the key is critical to flexibly"] # [doc = " supporting `git-config` sections, as duplicated keys are permitted."] pub (crate) sections : HashMap < SectionId , file :: Section < 'event > > , # [doc = " Internal monotonically increasing counter for section ids."] pub (crate) section_id_counter : usize , # [doc = " Section order for output ordering."] pub (crate) section_order : VecDeque < SectionId > , # [doc = " The source of the File itself, which is attached to new sections automatically."] pub (crate) meta : OwnShared < Metadata > , }
    };
}

